# owner: platform
import unittest

from hourglass.rounding import round_minutes, round_spans, rounded_labels
from hourglass.parsing import parse_span
from hourglass.models import Span

class RoundMinutesTests(unittest.TestCase):
    def test_nearest_step(self):
        self.assertEqual(round_minutes(62, 15), 60)
        self.assertEqual(round_minutes(68, 15), 75)

    def test_halfway_rounds_up(self):
        self.assertEqual(round_minutes(45, 30), 60)
        self.assertEqual(round_minutes(65, 10), 70)

    def test_exact_multiple_is_unchanged(self):
        self.assertEqual(round_minutes(540, 15), 540)

class RoundSpansTests(unittest.TestCase):
    def test_rounds_both_ends(self):
        result = round_spans([parse_span("09:03-17:12")], 15)
        self.assertEqual(result, [Span(540, 1035)])

    def test_end_of_day_stays_valid(self):
        result = round_spans([parse_span("20:00-23:58")], 15)
        self.assertEqual(result, [Span(1200, 1440)])

    def test_empty_list(self):
        self.assertEqual(round_spans([], 15), [])

    def test_bad_steps_raise(self):
        spans = [Span(540, 600)]
        for step in (0, -15, 7, 45, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_spans(spans, step)

    def test_span_that_collapses_raises(self):
        with self.assertRaises(ValueError):
            round_spans([Span(541, 545)], 15)

class LabelTests(unittest.TestCase):
    def test_label_format(self):
        labels = rounded_labels([parse_span("09:00-17:15")], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_labels_use_rounded_times(self):
        spans = [parse_span("08:58-12:01"), parse_span("13:00-13:30")]
        self.assertEqual(
            rounded_labels(spans, 30),
            ["09:00-12:00 (3h 0m)", "13:00-13:30 (0h 30m)"]
        )

if __name__ == "__main__":
    unittest.main()
